export function sortearFace(aleatorio = Math.random) {
  const valor = aleatorio();
  if (!(valor >= 0 && valor < 1)) throw new RangeError('aleatorio deve devolver número em [0, 1)');
  return Math.floor(valor * 6) + 1;
}

